//! Internal `COMMENT` plugin: ruled comment blocks for generated files.
//!
//! File banners and section dividers rendered from one width and one
//! rule style, so every generated script and action carries the same
//! comment voice no matter which template placed it. Pure string
//! functions, callable directly in `{{ }}` placeholders with no
//! import. Multi-line bodies ride `"""` blocks, which lower exactly
//! like statement-position block strings; the footer directory arrives
//! as a bare `$template_dir` scope read (never a nested `{{ }}`):
//! `{{ COMMENT::BANNER("Title", """Line one.""", "#", $template_dir) }}`.
//! Section dividers take the same body shape plus an explicit indent
//! so multi-line sections stay aligned at any nesting depth.
//! Registered only by `crate::run`; reusable by any pipeline that
//! generates commented files, registered by no other surface.

use anyhow::{Context, Result};
use oxdock_core::{HostModule, OxDockFn, TypeTag, Value};
use oxdock_func_macro::oxdock_func;
use oxdock_process::ProcessManager;

/// Fill width after `marker + " "`: every ruled line totals 71
/// columns under `#`. Widths count Unicode scalars, never UTF-8
/// bytes, so non-ASCII titles still pad to the same column.
const FILL: usize = 69;

fn has_line_break(s: &str) -> bool {
    s.contains(['\n', '\r'])
}

fn check_marker(marker: &str) -> Result<()> {
    anyhow::ensure!(
        !marker.is_empty() && !marker.chars().any(char::is_whitespace),
        "marker must be one non-blank token, got {marker:?}"
    );
    Ok(())
}

fn rule_line(marker: &str, fill: char) -> Result<String> {
    check_marker(marker)?;
    Ok(format!("{marker} {}", fill.to_string().repeat(FILL)))
}

fn section_text(title: &str, body: &str, marker: &str, indent: &str) -> Result<String> {
    check_marker(marker)?;
    anyhow::ensure!(
        !title.is_empty() && !has_line_break(title),
        "section title must be one non-empty line, got {title:?}"
    );
    anyhow::ensure!(
        indent.chars().all(|c| c == ' ' || c == '\t'),
        "section indent must be whitespace only, got {indent:?}"
    );
    let head = format!("{marker} ---- {title} ");
    let total = marker.chars().count() + 1 + FILL;
    let rest = total
        .checked_sub(head.chars().count())
        .with_context(|| format!("section title too long: {title:?}"))?;
    anyhow::ensure!(
        rest >= 2,
        "section title leaves no trailing rule: {title:?}"
    );
    let mut out = vec![format!("{head}{}", "-".repeat(rest))];
    // The divider rides the template's own line indentation; every
    // body line below carries the caller-passed indent explicitly, so
    // the block stays aligned at any nesting depth. An empty body
    // means divider only; whitespace-only lines render bare.
    if !body.trim().is_empty() {
        for line in body.split('\n') {
            anyhow::ensure!(
                !line.contains('\r'),
                "section body lines must not carry carriage returns, got {line:?}"
            );
            if line.trim().is_empty() {
                out.push(format!("{indent}{marker}"));
            } else {
                out.push(format!("{indent}{marker} {line}"));
            }
        }
    }
    Ok(out.join("\n"))
}

fn banner_text(title: &str, body: &str, marker: &str, template_dir: &str) -> Result<String> {
    check_marker(marker)?;
    anyhow::ensure!(
        !title.is_empty() && !has_line_break(title),
        "banner title must be one non-empty line, got {title:?}"
    );
    anyhow::ensure!(
        !has_line_break(template_dir),
        "banner template dir must be one line, got {template_dir:?}"
    );
    let title_line = format!("{marker} {title}");
    anyhow::ensure!(
        title_line.chars().count() <= marker.chars().count() + 1 + FILL,
        "banner title too long: {title:?}"
    );
    let mut out = vec![rule_line(marker, '=')?, title_line, marker.to_string()];
    if !body.is_empty() {
        for line in body.split('\n') {
            anyhow::ensure!(
                !line.contains('\r'),
                "banner body lines must not carry carriage returns, got {line:?}"
            );
            if line.is_empty() {
                out.push(marker.to_string());
            } else {
                out.push(format!("{marker} {line}"));
            }
        }
    }
    if !template_dir.is_empty() {
        out.push(marker.to_string());
        out.push(format!(
            "{marker} GENERATED by oxdock-render from `{template_dir}/`:"
        ));
        out.push(format!("{marker} do not edit by hand."));
    }
    out.push(rule_line(marker, '=')?);
    Ok(out.join("\n"))
}

/// One bare rule line: `{{ COMMENT::RULE("#") }}`.
#[oxdock_func(pure, returns = TypeTag::String)]
fn rule(marker: String) -> Result<Value> {
    Ok(Value::string(
        rule_line(&marker, '=').context("COMMENT::RULE")?,
    ))
}

/// One section divider with an optional body: `{{ COMMENT::SECTION("Release installs", """Body line.""", "#", "    ") }}`.
/// The divider is single-line and rides the template's own line
/// indentation; every body line carries the caller-passed indent
/// explicitly (whitespace only), so the block stays aligned at any
/// nesting depth. An empty body means divider only.
#[oxdock_func(pure, returns = TypeTag::String)]
fn section(title: String, body: String, marker: String, indent: String) -> Result<Value> {
    Ok(Value::string(
        section_text(&title, &body, &marker, &indent).context("COMMENT::SECTION")?,
    ))
}

/// Full file banner for column zero: title, blank, body lines, an
/// optional `GENERATED by ...` footer naming the template directory,
/// rule above and below. The body is one string, usually a `"""`
/// block; its lines render in order, empty lines as bare marker
/// lines. Pass the footer directory as a bare `$template_dir`
/// scope read (never a nested `{{ }}`): empty means no footer.
#[oxdock_func(pure, returns = TypeTag::String)]
fn banner(title: String, body: String, marker: String, template_dir: String) -> Result<Value> {
    Ok(Value::string(
        banner_text(&title, &body, &marker, &template_dir).context("COMMENT::BANNER")?,
    ))
}

/// The internal `COMMENT` plugin for the render engine. Registered
/// only by `crate::run`; the core language never sees it.
pub fn module<P: ProcessManager>() -> HostModule<P> {
    HostModule {
        name: "COMMENT".to_string(),
        funcs: vec![
            Rule::registration(),
            Section::registration(),
            Banner::registration(),
        ],
        types: vec![],
        record_schemas: vec![],
        states: Vec::new(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rule_is_canonical_width() {
        let line = rule_line("#", '=').expect("rule");
        assert_eq!(line.len(), 71);
        assert_eq!(line, format!("# {}", "=".repeat(69)));
    }

    #[test]
    fn section_pads_to_canonical_width() {
        let line = section_text("Release installs", "", "#", "").expect("section");
        assert_eq!(
            line,
            "# ---- Release installs -----------------------------------------------"
        );
        assert_eq!(line.chars().count(), 71);
    }

    #[test]
    fn section_counts_scalars_not_bytes() {
        // `é` is two UTF-8 bytes but one column: padding must still
        // land the rule at 71 scalars.
        let line = section_text("Café installs", "", "#", "").expect("section");
        assert_eq!(line.chars().count(), 71);
        assert!(line.ends_with("--"));
    }

    #[test]
    fn section_body_rides_explicit_indent() {
        let out = section_text(
            "Release installs",
            "One leg per shell.\n\nTwo lines.",
            "#",
            "    ",
        )
        .expect("section");
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(lines.len(), 4);
        assert_eq!(lines[0].chars().count(), 71);
        assert_eq!(lines[1], "    # One leg per shell.");
        assert_eq!(lines[2], "    #");
        assert_eq!(lines[3], "    # Two lines.");
    }

    #[test]
    fn banner_shapes_title_body_and_rules() {
        let out = banner_text("Title here.", "First line.\n\nLast line.", "#", "").expect("banner");
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(lines.len(), 7);
        assert_eq!(lines[0], lines[6]);
        assert_eq!(lines[0], format!("# {}", "=".repeat(69)));
        assert_eq!(lines[1], "# Title here.");
        assert_eq!(lines[2], "#");
        assert_eq!(lines[3], "# First line.");
        assert_eq!(lines[4], "#");
        assert_eq!(lines[5], "# Last line.");
    }

    #[test]
    fn banner_footer_names_the_template_dir() {
        let out = banner_text("Title here.", "Body.", "#", ".oxdock/template/x").expect("banner");
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(lines.len(), 8);
        assert_eq!(lines[4], "#");
        assert_eq!(
            lines[5],
            "# GENERATED by oxdock-render from `.oxdock/template/x/`:"
        );
        assert_eq!(lines[6], "# do not edit by hand.");
        assert_eq!(lines[7], lines[0]);
    }

    #[test]
    fn empty_body_skips_the_body_block() {
        let out = banner_text("Title here.", "", "#", "").expect("banner");
        let lines: Vec<&str> = out.lines().collect();
        assert_eq!(lines.len(), 4);
        assert_eq!(lines[2], "#");
    }

    #[test]
    fn rejects_overlong_and_blank_shapes() {
        assert!(section_text("", "", "#", "").is_err());
        assert!(section_text("a\nb", "", "#", "").is_err());
        assert!(section_text("a\rb", "", "#", "").is_err());
        assert!(section_text(&"x".repeat(200), "", "#", "").is_err());
        // 62 columns of title leave zero trailing dashes: rejected.
        assert!(section_text(&"x".repeat(62), "", "#", "").is_err());
        assert!(section_text("ok", "", "", "").is_err());
        assert!(section_text("ok", "", "# #", "").is_err());
        assert!(section_text("ok", "a\rb", "#", "    ").is_err());
        assert!(section_text("ok", "body", "#", "  \n ").is_err());
        assert!(rule_line("", '=').is_err());
        assert!(banner_text("", "body", "#", "").is_err());
        assert!(banner_text(&"x".repeat(200), "body", "#", "").is_err());
        assert!(banner_text("ok", "a\rb", "#", "").is_err());
        assert!(banner_text("ok", "body", "#", "a\rb").is_err());
    }
}
